CREATE TABLE IF NOT EXISTS reservation_history (id INTEGER PRIMARY KEY AUTOINCREMENT, reservation_id TEXT NOT NULL REFERENCES reservations(id), action TEXT NOT NULL, actor TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS reservation_history_reservation ON reservation_history(reservation_id,id);
CREATE TRIGGER IF NOT EXISTS reservation_history_created AFTER INSERT ON reservations BEGIN INSERT INTO reservation_history(reservation_id,action) VALUES(NEW.id,'Pedido registado'); END;
CREATE TRIGGER IF NOT EXISTS reservation_history_status AFTER UPDATE OF status ON reservations WHEN OLD.status IS NOT NEW.status BEGIN INSERT INTO reservation_history(reservation_id,action) VALUES(NEW.id,'Estado: ' || OLD.status || ' → ' || NEW.status); END;
CREATE TRIGGER IF NOT EXISTS reservation_history_schedule AFTER UPDATE OF date,time,people,children,babies,chair ON reservations WHEN OLD.date IS NOT NEW.date OR OLD.time IS NOT NEW.time OR OLD.people IS NOT NEW.people OR OLD.children IS NOT NEW.children OR OLD.babies IS NOT NEW.babies OR OLD.chair IS NOT NEW.chair BEGIN INSERT INTO reservation_history(reservation_id,action) VALUES(NEW.id,'Data, hora ou grupo alterados'); END;
CREATE TRIGGER IF NOT EXISTS reservation_history_contact AFTER UPDATE OF name,phone,email,message ON reservations WHEN OLD.name IS NOT NEW.name OR OLD.phone IS NOT NEW.phone OR OLD.email IS NOT NEW.email OR OLD.message IS NOT NEW.message BEGIN INSERT INTO reservation_history(reservation_id,action) VALUES(NEW.id,'Contactos ou observações alterados'); END;
CREATE TRIGGER IF NOT EXISTS reservation_history_tables AFTER UPDATE OF table_ids ON reservations WHEN OLD.table_ids IS NOT NEW.table_ids BEGIN INSERT INTO reservation_history(reservation_id,action) VALUES(NEW.id,'Mesas alteradas'); END;
